SELECT 'ai_message_with_sender', id::text, role::text
FROM "Message"
WHERE role IN ('AI', 'SYSTEM') AND "senderId" IS NOT NULL;
-- An AI/SYSTEM row with a sender is a human authoring as the facilitator
