-- ----------------------------------------------------------------------------
-- P13 session_without_two_participants (the step-4a assertion, checked before any copy; T-cardinality-1)
-- ----------------------------------------------------------------------------
SELECT 'session_without_two_participants', s.id::text,
       s.status::text || ', participants: ' || coalesce((SELECT string_agg(DISTINCT p.user_id::text, ', ') FROM pg_temp.pair p WHERE p.session_id = s.id), 'none')
FROM "Session" s
WHERE s.status IN ('ACTIVE', 'WAITING', 'PAUSED', 'RESOLVED')
  AND (SELECT count(DISTINCT p.user_id) FROM pg_temp.pair p WHERE p.session_id = s.id) < 2
  AND NOT (s.status <> 'RESOLVED'
           AND EXISTS (SELECT 1 FROM pg_temp.pair p JOIN pg_temp.vanished v USING (user_id) WHERE p.session_id = s.id));
-- An ACTIVE/WAITING/PAUSED/RESOLVED session with fewer than two participants
-- (T-cardinality-1; step 4a). If the partner never joined it was never
-- active: move it back to INVITED (and its invitation to PENDING), or
-- ABANDONED if it is over.
-- UPDATE "Session" SET status = 'INVITED' WHERE id IN (<ids>);
-- UPDATE "Invitation" SET status = 'PENDING', "acceptedAt" = NULL WHERE "sessionId" IN (<ids>) AND status = 'ACCEPTED';

-- ----------------------------------------------------------------------------
-- P14a invitation_accepted_without_accepted_at (CHECK, P3 §6)
-- ----------------------------------------------------------------------------
SELECT 'invitation_accepted_without_accepted_at', id::text, NULL
FROM "Invitation"
WHERE status = 'ACCEPTED' AND "acceptedAt" IS NULL;
-- CHECK: an ACCEPTED invitation records when.
-- UPDATE "Invitation" i SET "acceptedAt" = (SELECT min(m."joinedAt") FROM "RelationshipMember" m JOIN "Session" s ON s."relationshipId" = m."relationshipId"
--   WHERE s.id = i."sessionId" AND m."userId" <> i."invitedById") WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P14b invitation_accepted_without_unique_acceptor (accepted_by_user_id = the one non-inviter participant, vanished ones included)
-- ----------------------------------------------------------------------------
SELECT 'invitation_accepted_without_unique_acceptor', i.id::text,
       (SELECT count(DISTINCT p.user_id) FROM pg_temp.pair p WHERE p.session_id = i."sessionId" AND p.user_id <> i."invitedById")::text
       || ' non-inviter participant(s)'
FROM "Invitation" i
WHERE i.status = 'ACCEPTED'
  AND (SELECT count(DISTINCT p.user_id) FROM pg_temp.pair p WHERE p.session_id = i."sessionId" AND p.user_id <> i."invitedById") <> 1;
-- accepted_by_user_id (new, P3 §6) is the session's one participant other
-- than the inviter (a vanished acceptor counts: their evidence names them).
-- Zero: nobody accepted (→ PENDING); several: decide who.
-- UPDATE "Invitation" SET status = 'PENDING', "acceptedAt" = NULL WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P15a attempt_without_author (empathy_attempt.author NOT NULL; not recoverable from vanished-member evidence)
-- ----------------------------------------------------------------------------
SELECT 'attempt_without_author', id::text, NULL
FROM pg_temp.empathy_attempt_src
WHERE "sourceUserId" IS NULL;
-- sourceUserId was nulled (author deleted) and the migration could not
-- recover it (it recovers the session's one vanished member without another
-- attempt there). Name the author from the app logs if known (a vanished id
-- needs other evidence in the session, e.g. a Message.forUserId); otherwise
-- the attempt cannot be attributed.
-- UPDATE "EmpathyAttempt" SET "sourceUserId" = '<user id>' WHERE id = '<attempt id>';

-- ----------------------------------------------------------------------------
-- P15b attempt_without_unique_subject (step 11: subject = the other participant; RAISE if N≠2)
-- ----------------------------------------------------------------------------
SELECT 'attempt_without_unique_subject', a.id::text,
       (SELECT count(DISTINCT p.user_id) FROM pg_temp.pair p WHERE p.session_id = a."sessionId" AND p.user_id <> a."sourceUserId")::text
       || ' other participant(s)'
FROM pg_temp.empathy_attempt_src a
WHERE a."sourceUserId" IS NOT NULL
  AND (SELECT count(DISTINCT p.user_id) FROM pg_temp.pair p WHERE p.session_id = a."sessionId" AND p.user_id <> a."sourceUserId") <> 1;
-- An attempt needs exactly one other participant as its subject. None: the
-- partner never joined — the attempt is about nobody; its statement stays in
-- the author's chat. Delete it (and its draft / EMPATHY_DRAFT consent).
-- DELETE FROM "ConsentRecord" WHERE "targetType" = 'EMPATHY_DRAFT' AND "targetId" IN (<draft ids>);
-- DELETE FROM "EmpathyAttempt" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P15c empathy_draft_without_unique_subject (draft.about_participant_id = the other participant)
-- ----------------------------------------------------------------------------
SELECT 'empathy_draft_without_unique_subject', d.id::text,
       (SELECT count(DISTINCT p.user_id) FROM pg_temp.pair p WHERE p.session_id = d."sessionId" AND p.user_id <> d."userId")::text
       || ' other participant(s)'
FROM "EmpathyDraft" d
WHERE (SELECT count(DISTINCT p.user_id) FROM pg_temp.pair p WHERE p.session_id = d."sessionId" AND p.user_id <> d."userId") <> 1;
-- As attempt_without_unique_subject, for the draft.
-- DELETE FROM "EmpathyDraft" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P15d attempt_revealed_without_revealed_at (CHECK REVEALED/VALIDATED → revealed_at)
-- ----------------------------------------------------------------------------
SELECT 'attempt_revealed_without_revealed_at', id::text, status::text
FROM pg_temp.empathy_attempt_src
WHERE status IN ('REVEALED', 'VALIDATED') AND "revealedAt" IS NULL;
-- CHECK REVEALED/VALIDATED → revealed_at. It was revealed no later than its
-- validation: use that, else delivery, else submission.
-- UPDATE "EmpathyAttempt" a SET "revealedAt" = coalesce((SELECT min(v."validatedAt") FROM "EmpathyValidation" v WHERE v."attemptId" = a.id),
--   a."deliveredAt", a."sharedAt") WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P16a validation_without_reviewer (empathy_review.reviewer NOT NULL; not recoverable as the attempt subject)
-- ----------------------------------------------------------------------------
SELECT 'validation_without_reviewer', id::text, NULL
FROM pg_temp.empathy_validation_src
WHERE "userId" IS NULL;
-- The reviewer was deleted (userId nulled) and the attempt has no single
-- other participant to recover them as (the migration does that itself).
-- UPDATE "EmpathyValidation" v SET "userId" = <the attempt's other member> WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P16b validation_reviewer_is_author (reviewer = the subject of the attempt)
-- ----------------------------------------------------------------------------
SELECT 'validation_reviewer_is_author', v.id::text, NULL
FROM pg_temp.empathy_validation_src v JOIN pg_temp.empathy_attempt_src a ON a.id = v."attemptId"
WHERE v."userId" = a."sourceUserId";
-- An author reviewing their own attempt: not a review. Delete.
-- DELETE FROM "EmpathyValidation" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P16c validation_draft_without_partner_attempt (draft(VALIDATION_FEEDBACK).attempt = the attempt of the partner)
-- ----------------------------------------------------------------------------
SELECT 'validation_draft_without_partner_attempt', d.id::text,
       (SELECT count(*) FROM pg_temp.empathy_attempt_src a WHERE a."sessionId" = d."sessionId" AND a."sourceUserId" <> d."userId")::text || ' partner attempt(s)'
FROM "ValidationFeedbackDraft" d
WHERE (SELECT count(*) FROM pg_temp.empathy_attempt_src a WHERE a."sessionId" = d."sessionId" AND a."sourceUserId" <> d."userId") <> 1;
-- A feedback draft needs the partner's attempt; without one it reviews nothing.
-- DELETE FROM "ValidationFeedbackDraft" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P17a reconciler_result_without_attempt (result → attempt by (session, guesser))
-- ----------------------------------------------------------------------------
SELECT 'reconciler_result_without_attempt', r.id::text, r."guesserId"
FROM "ReconcilerResult" r
WHERE NOT EXISTS (SELECT 1 FROM pg_temp.empathy_attempt_src a
                  WHERE a."sessionId" = r."sessionId" AND a."sourceUserId" = pg_temp.as_uuid(r."guesserId"));
-- A result whose guesser has no attempt in the session: stale. Delete (its
-- share offer cascades).
-- DELETE FROM "ReconcilerResult" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P17b reconciler_result_two_current (sql_result_one_current)
-- ----------------------------------------------------------------------------
SELECT 'reconciler_result_two_current', "sessionId"::text || ':' || "guesserId" || '->' || "subjectId",
       string_agg(id::text, ', ' ORDER BY id)
FROM "ReconcilerResult"
WHERE "supersededAt" IS NULL
GROUP BY "sessionId", "guesserId", "subjectId"
HAVING count(*) > 1;
-- sql_result_one_current: supersede all but the newest.
-- UPDATE "ReconcilerResult" SET "supersededAt" = now() WHERE id IN (<older ids>);

-- ----------------------------------------------------------------------------
-- P17c reconciler_result_duplicate_iteration (UNIQUE (attempt_id, iteration))
-- ----------------------------------------------------------------------------
SELECT 'reconciler_result_duplicate_iteration', "sessionId"::text || ':' || "guesserId" || ' #' || iteration,
       string_agg(id::text, ', ' ORDER BY id)
FROM "ReconcilerResult"
GROUP BY "sessionId", "guesserId", iteration
HAVING count(*) > 1;
-- UNIQUE (attempt, iteration): renumber the older rows.
-- UPDATE "ReconcilerResult" SET iteration = <n> WHERE id = '<id>';

-- ----------------------------------------------------------------------------
-- P17d reconciler_result_enum (gap_severity / recommender_action)
-- ----------------------------------------------------------------------------
SELECT 'reconciler_result_enum', id::text, format('gapSeverity=%L recommendedAction=%L', "gapSeverity", "recommendedAction")
FROM "ReconcilerResult"
WHERE upper("gapSeverity") NOT IN ('NONE', 'MINOR', 'MODERATE', 'SIGNIFICANT')
   OR "recommendedAction" NOT IN ('PROCEED', 'OFFER_OPTIONAL', 'OFFER_SHARING');
-- gapSeverity / recommendedAction become enums; map the stray value.
-- UPDATE "ReconcilerResult" SET "gapSeverity" = 'moderate' WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P17e reconciler_result_self (CHECK author <> subject)
-- ----------------------------------------------------------------------------
SELECT 'reconciler_result_self', id::text, NULL
FROM "ReconcilerResult"
WHERE "guesserId" = "subjectId";
-- A self-guess is a parameter swap bug; delete.
-- DELETE FROM "ReconcilerResult" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P17f reconciler_result_score_range (CHECK alignment_score 0..100)
-- ----------------------------------------------------------------------------
SELECT 'reconciler_result_score_range', id::text, "alignmentScore"::text
FROM "ReconcilerResult"
WHERE "alignmentScore" NOT BETWEEN 0 AND 100;
-- CHECK alignment_score 0..100.
-- UPDATE "ReconcilerResult" SET "alignmentScore" = least(greatest("alignmentScore", 0), 100) WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P18a share_offer_status_dates (CHECK ACCEPTED ⇔ shared_at, DECLINED ⇔ declined_at)
-- ----------------------------------------------------------------------------
SELECT 'share_offer_status_dates', id::text, format('status=%s sharedAt=%s declinedAt=%s', status, "sharedAt", "declinedAt")
FROM "ReconcilerShareOffer"
WHERE (status = 'ACCEPTED') <> ("sharedAt" IS NOT NULL)
   OR (status = 'DECLINED') <> ("declinedAt" IS NOT NULL);
-- CHECK ACCEPTED ⇔ sharedAt and DECLINED ⇔ declinedAt.
-- UPDATE "ReconcilerShareOffer" SET "declinedAt" = "updatedAt" WHERE status = 'DECLINED' AND "declinedAt" IS NULL AND id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P18b share_offer_user_not_subject (context_share_offer.subject = result.subject)
-- ----------------------------------------------------------------------------
SELECT 'share_offer_user_not_subject', o.id::text, o."userId" || ' <> ' || r."subjectId"
FROM "ReconcilerShareOffer" o JOIN "ReconcilerResult" r ON r.id = o."resultId"
WHERE o."userId" <> r."subjectId";
-- The offer goes to the result's subject.
-- UPDATE "ReconcilerShareOffer" o SET "userId" = r."subjectId" FROM "ReconcilerResult" r WHERE r.id = o."resultId" AND o.id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P18c share_offer_duplicate_iteration (UNIQUE (attempt_id, iteration))
-- ----------------------------------------------------------------------------
SELECT 'share_offer_duplicate_iteration', r."sessionId"::text || ':' || r."guesserId" || ' #' || o.iteration,
       string_agg(o.id::text, ', ' ORDER BY o.id)
FROM "ReconcilerShareOffer" o JOIN "ReconcilerResult" r ON r.id = o."resultId"
GROUP BY r."sessionId", r."guesserId", o.iteration
HAVING count(*) > 1;
-- UNIQUE (attempt, iteration): renumber or drop the offer of a superseded result.
-- UPDATE "ReconcilerShareOffer" SET iteration = <n> WHERE id = '<id>';

-- ----------------------------------------------------------------------------
-- P19a consent_decision_undated (CHECK (decision IS NULL) = (decided_at IS NULL), P3 §6)
-- ----------------------------------------------------------------------------
SELECT 'consent_decision_undated', id::text, format('decision=%s decidedAt=%s', decision, "decidedAt")
FROM "ConsentRecord"
WHERE (decision IS NULL) <> ("decidedAt" IS NULL);
-- CHECK (decision IS NULL) = (decided_at IS NULL).
-- UPDATE "ConsentRecord" SET "decidedAt" = "createdAt" WHERE decision IS NOT NULL AND "decidedAt" IS NULL AND id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P19b consent_revoked_not_revoked (CHECK revoked_at IS NULL OR decision = REVOKED)
-- ----------------------------------------------------------------------------
SELECT 'consent_revoked_not_revoked', id::text, format('decision=%s', decision)
FROM "ConsentRecord"
WHERE "revokedAt" IS NOT NULL AND decision IS DISTINCT FROM 'REVOKED';
-- A revokedAt implies decision REVOKED.
-- UPDATE "ConsentRecord" SET decision = 'REVOKED' WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P20a consented_content_target (need_share.need_id via consentRecordId → ConsentRecord.targetId)
-- ----------------------------------------------------------------------------
SELECT 'consented_content_target', cc.id::text, cr."targetType"::text || ':' || coalesce(cr."targetId", 'NULL')
FROM "ConsentedContent" cc JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId"
WHERE cr."targetType" <> 'IDENTIFIED_NEED'
   OR NOT EXISTS (SELECT 1 FROM "IdentifiedNeed" n WHERE n.id = pg_temp.as_uuid(cr."targetId"))
   OR (cc."originalNeedId" IS NOT NULL AND cc."originalNeedId" IS DISTINCT FROM pg_temp.as_uuid(cr."targetId"));
-- need_share is found through consentRecordId → ConsentRecord.targetId (an
-- IdentifiedNeed). Point the record at the need that was shared.
-- UPDATE "ConsentRecord" SET "targetType" = 'IDENTIFIED_NEED', "targetId" = '<need id>' WHERE id = '<record id>';

-- ----------------------------------------------------------------------------
-- P20b consented_content_duplicate_need (need_share PK need_id)
-- ----------------------------------------------------------------------------
SELECT 'consented_content_duplicate_need', cr."targetId", string_agg(cc.id::text, ', ' ORDER BY cc.id)
FROM "ConsentedContent" cc JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId"
GROUP BY cr."targetId"
HAVING count(*) > 1;
-- need_share is keyed by need: one shared row per need. Keep the live one.
-- DELETE FROM "ConsentedContent" WHERE id IN (<duplicate ids>);

-- ----------------------------------------------------------------------------
-- P20c consented_content_revocation (inactive needs revokedAt; CHECK revoked_at >= shared_at)
-- ----------------------------------------------------------------------------
SELECT 'consented_content_revocation', id::text, format('consentActive=%s revokedAt=%s consentedAt=%s', "consentActive", "revokedAt", "consentedAt")
FROM "ConsentedContent"
WHERE (NOT "consentActive" AND "revokedAt" IS NULL) OR "revokedAt" < "consentedAt";
-- An inactive row records when it was revoked; revocation follows consent.
-- UPDATE "ConsentedContent" SET "revokedAt" = greatest("consentedAt", coalesce("revokedAt", "consentedAt")) WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P20d consented_content_session (session of the need owner = SharedVessel session)
-- ----------------------------------------------------------------------------
SELECT 'consented_content_session', cc.id::text, NULL
FROM "ConsentedContent" cc
JOIN "ConsentRecord" cr ON cr.id = cc."consentRecordId"
JOIN "SharedVessel" sv ON sv.id = cc."sharedVesselId"
JOIN "IdentifiedNeed" n ON n.id = pg_temp.as_uuid(cr."targetId")
JOIN "UserVessel" uv ON uv.id = n."vesselId"
WHERE uv."sessionId" <> sv."sessionId";
-- The shared need must belong to the session it was shared into.
-- (Investigate: a need shared across sessions is a bug; delete the row.)
-- DELETE FROM "ConsentedContent" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P20e need_consent_unresolved (a granted IDENTIFIED_NEED ConsentRecord is a need_share: targetId must be a need)
-- ----------------------------------------------------------------------------
SELECT 'need_consent_unresolved', c.id::text, coalesce(c."targetId", 'NULL') || ' (' || c.decision::text || ')'
FROM "ConsentRecord" c
WHERE c."targetType" = 'IDENTIFIED_NEED' AND c.decision IN ('GRANTED', 'REVOKED')
  AND NOT EXISTS (SELECT 1 FROM "IdentifiedNeed" n WHERE n.id = pg_temp.as_uuid(c."targetId"));
-- A granted IDENTIFIED_NEED ConsentRecord is a shared need (the Stage 3
-- share-needs handler writes no ConsentedContent), so its targetId must name
-- an IdentifiedNeed. Point it at the need that was shared. If that need is
-- gone, the owner decides; ConsentRecord rows are not deleted by fix-data
-- (ruling R18).
-- UPDATE "ConsentRecord" SET "targetId" = '<need id>' WHERE id = '<record id>';

-- ----------------------------------------------------------------------------
-- P20g need_consent_revocation (CHECK need_share.revoked_at >= shared_at for a record-sourced share)
-- ----------------------------------------------------------------------------
SELECT 'need_consent_revocation', c.id::text, format('decidedAt=%s createdAt=%s revokedAt=%s', c."decidedAt", c."createdAt", c."revokedAt")
FROM "ConsentRecord" c
WHERE c."targetType" = 'IDENTIFIED_NEED' AND c.decision IN ('GRANTED', 'REVOKED')
  AND NOT EXISTS (SELECT 1 FROM "ConsentedContent" xcc JOIN "ConsentRecord" xcr ON xcr.id = xcc."consentRecordId"
                  WHERE pg_temp.as_uuid(xcr."targetId") = pg_temp.as_uuid(c."targetId"))
  AND c."revokedAt" < coalesce(c."decidedAt", c."createdAt");
-- A share cannot be revoked before it was granted (need_share CHECK).
-- UPDATE "ConsentRecord" SET "revokedAt" = coalesce("decidedAt", "createdAt") WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P21 proposal_removed_dates (CHECK (status = REMOVED) = (removed_at IS NOT NULL))
-- ----------------------------------------------------------------------------
SELECT 'proposal_removed_dates', id::text, format('status=%s removedAt=%s', status, "removedAt")
FROM "StrategyProposal"
WHERE (status = 'REMOVED') <> ("removedAt" IS NOT NULL);
-- CHECK (status = REMOVED) = (removed_at IS NOT NULL).
-- UPDATE "StrategyProposal" SET "removedAt" = "updatedAt" WHERE status = 'REMOVED' AND "removedAt" IS NULL AND id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P22a agreement_duplicate_proposal (UNIQUE agreement.proposal_id)
-- ----------------------------------------------------------------------------
SELECT 'agreement_duplicate_proposal', "proposalId"::text, string_agg(id::text, ', ' ORDER BY id)
FROM "Agreement"
WHERE "proposalId" IS NOT NULL AND (status <> 'PROPOSED' OR ("agreedByA" AND "agreedByB"))
GROUP BY "proposalId"
HAVING count(*) > 1;
-- One agreement per proposal: keep the live one.
-- DELETE FROM "Agreement" WHERE id IN (<duplicate ids>);

-- ----------------------------------------------------------------------------
-- P22b agreement_parties_incomplete (T-agreement-parties: every participant is a party)
-- ----------------------------------------------------------------------------
SELECT 'agreement_parties_incomplete', id::text, format('status=%s agreedByA=%s agreedByB=%s', status, "agreedByA", "agreedByB")
FROM "Agreement"
WHERE status <> 'PROPOSED' AND NOT ("agreedByA" AND "agreedByB");
-- T-agreement-parties: an agreement names every participant. One party
-- missing: it was never agreed — PROPOSED (dropped by the migration) — or
-- both did agree (set the flag).
-- UPDATE "Agreement" SET status = 'PROPOSED' WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P22c agreement_party_not_willing (T-agreement-parties: every party WILLING)
-- ----------------------------------------------------------------------------
SELECT 'agreement_party_not_willing', a.id::text, 'NOT_WILLING selection ' || s.id::text
FROM "Agreement" a
JOIN "Stage4ProposalSelection" s ON s."proposalId" = a."proposalId" AND s.decision = 'NOT_WILLING'
WHERE a.status <> 'PROPOSED' OR (a."agreedByA" AND a."agreedByB");
-- A party said NOT_WILLING on the agreed proposal: one of the two is wrong.
-- UPDATE "Stage4ProposalSelection" SET decision = 'WILLING' WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P23a revision_action_unknown (action → revision_action, upper snake)
-- ----------------------------------------------------------------------------
SELECT 'revision_action_unknown', id::text, action
FROM "Stage4ProposalRevision"
WHERE upper(regexp_replace(regexp_replace(action, '([a-z0-9])([A-Z])', '\1_\2', 'g'), '[^A-Za-z0-9]+', '_', 'g'))
      NOT IN ('CREATED', 'REVISED', 'REMOVED', 'RESTORED', 'CONVERTED', 'CAPTURE_SKIPPED', 'COVERED', 'SUBCHAT_REFINED');
-- revision_action has 8 members; map the stray action.
-- UPDATE "Stage4ProposalRevision" SET action = 'REVISED' WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P23b revision_session_mismatch (sessionId asserted = that of the proposal, then dropped)
-- ----------------------------------------------------------------------------
SELECT 'revision_session_mismatch', r.id::text, r."sessionId" || ' <> ' || p."sessionId"::text
FROM "Stage4ProposalRevision" r JOIN "StrategyProposal" p ON p.id = r."proposalId"
WHERE r."sessionId" <> p."sessionId"::text;
-- The revision's sessionId must be its proposal's (it is then dropped).
-- UPDATE "Stage4ProposalRevision" r SET "sessionId" = p."sessionId"::text FROM "StrategyProposal" p WHERE p.id = r."proposalId" AND r.id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P23c revision_json_not_object (CHECK jsonb_typeof(before/after) = object)
-- ----------------------------------------------------------------------------
SELECT 'revision_json_not_object', id::text, format('before=%s after=%s', jsonb_typeof(before), jsonb_typeof(after))
FROM "Stage4ProposalRevision"
WHERE coalesce(jsonb_typeof(before), 'null') NOT IN ('object', 'null')
   OR coalesce(jsonb_typeof(after), 'null') NOT IN ('object', 'null');
-- before/after must be JSON objects.
-- UPDATE "Stage4ProposalRevision" SET before = jsonb_build_object('value', before) WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P24a follow_up_scope_owner (CHECK (scope = INDIVIDUAL) = (owner IS NOT NULL))
-- ----------------------------------------------------------------------------
SELECT 'follow_up_scope_owner', id::text, format('scope=%s ownerUserId=%s', scope, "ownerUserId")
FROM "TendingEntry"
WHERE (scope = 'INDIVIDUAL') <> ("ownerUserId" IS NOT NULL);
-- CHECK (scope = INDIVIDUAL) = (owner IS NOT NULL).
-- UPDATE "TendingEntry" SET scope = 'SHARED' WHERE "ownerUserId" IS NULL AND id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P24b reminder_status_unknown (text → reminder_status)
-- ----------------------------------------------------------------------------
SELECT 'reminder_status_unknown', id::text, status
FROM "TendingReminder"
WHERE status NOT IN ('SCHEDULED', 'DELIVERED', 'CANCELLED');
-- status becomes SCHEDULED | DELIVERED | CANCELLED.
-- UPDATE "TendingReminder" SET status = 'CANCELLED' WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P24c checkin_without_entry (a check-in must land on a follow_up)
-- ----------------------------------------------------------------------------
SELECT 'checkin_without_entry', c.id::text, NULL
FROM "TendingCheckin" c
WHERE NOT EXISTS (SELECT 1 FROM "TendingCoordinationCycle" y WHERE y.id = c."coordinationCycleId" AND cardinality(y."entryIds") > 0)
  AND NOT EXISTS (SELECT 1 FROM "TendingResponse" r WHERE r."checkinId" = c.id)
  AND NOT EXISTS (SELECT 1 FROM "TendingEntryOutcome" o WHERE o."checkinId" = c.id)
  AND NOT EXISTS (SELECT 1 FROM "TendingAdjustment" a WHERE a."checkinId" = c.id);
-- A check-in covering no entry has no follow_up to land on.
-- DELETE FROM "TendingCheckin" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P24d checkin_entry_duplicate (UNIQUE follow_up_checkin (follow_up_id, participant_id))
-- ----------------------------------------------------------------------------
WITH covers AS (
  SELECT c.id AS checkin_id, c."userId" AS user_id, e AS entry_id
  FROM "TendingCheckin" c
  JOIN "TendingCoordinationCycle" y ON y.id = c."coordinationCycleId"
  CROSS JOIN unnest(y."entryIds") AS e
  UNION SELECT r."checkinId", r."userId", r."tendingEntryId" FROM "TendingResponse" r WHERE r."checkinId" IS NOT NULL
  UNION SELECT o."checkinId", o."userId", o."tendingEntryId" FROM "TendingEntryOutcome" o
  UNION SELECT a."checkinId", a."userId", a."tendingEntryId" FROM "TendingAdjustment" a
)
SELECT 'checkin_entry_duplicate', entry_id::text || ':' || user_id::text, string_agg(DISTINCT checkin_id::text, ', ')
FROM covers
GROUP BY entry_id, user_id
HAVING count(DISTINCT checkin_id) > 1;
-- UNIQUE follow_up_checkin (follow_up, participant): two check-ins of one
-- user on one entry (successive periods). Keep the latest; its predecessor's
-- answers are history the target does not hold per period.
-- DELETE FROM "TendingCheckin" WHERE id IN (<older ids>);

-- ----------------------------------------------------------------------------
-- P24e cycle_entry_unknown (TendingCoordinationCycle.entryIds must be entries)
-- ----------------------------------------------------------------------------
SELECT 'cycle_entry_unknown', y.id::text, e::text
FROM "TendingCoordinationCycle" y CROSS JOIN unnest(y."entryIds") AS e
WHERE NOT EXISTS (SELECT 1 FROM "TendingEntry" t WHERE t.id = e);
-- entryIds names a deleted entry.
-- UPDATE "TendingCoordinationCycle" SET "entryIds" = array_remove("entryIds", '<id>') WHERE id = '<cycle id>';

-- ----------------------------------------------------------------------------
-- P25 text_id_not_uuid (step 17: every resolved value cast to uuid)
-- ----------------------------------------------------------------------------
SELECT 'text_id_not_uuid', id::text, 'Message.forUserId=' || "forUserId"
FROM "Message" WHERE "forUserId" IS NOT NULL AND pg_temp.as_uuid("forUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ReconcilerResult.guesserId=' || "guesserId"
FROM "ReconcilerResult" WHERE "guesserId" IS NOT NULL AND pg_temp.as_uuid("guesserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ReconcilerResult.subjectId=' || "subjectId"
FROM "ReconcilerResult" WHERE "subjectId" IS NOT NULL AND pg_temp.as_uuid("subjectId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ReconcilerShareOffer.userId=' || "userId"
FROM "ReconcilerShareOffer" WHERE "userId" IS NOT NULL AND pg_temp.as_uuid("userId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4NeedDeclination.userId=' || "userId"
FROM "Stage4NeedDeclination" WHERE "userId" IS NOT NULL AND pg_temp.as_uuid("userId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4NeedDeclination.needId=' || "needId"
FROM "Stage4NeedDeclination" WHERE "needId" IS NOT NULL AND pg_temp.as_uuid("needId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4ProposalRevision.actorUserId=' || "actorUserId"
FROM "Stage4ProposalRevision" WHERE "actorUserId" IS NOT NULL AND pg_temp.as_uuid("actorUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'Stage4Closure.closedByUserId=' || "closedByUserId"
FROM "Stage4Closure" WHERE "closedByUserId" IS NOT NULL AND pg_temp.as_uuid("closedByUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'TendingEntry.ownerUserId=' || "ownerUserId"
FROM "TendingEntry" WHERE "ownerUserId" IS NOT NULL AND pg_temp.as_uuid("ownerUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'TendingNeedOutcome.sourceUserId=' || "sourceUserId"
FROM "TendingNeedOutcome" WHERE "sourceUserId" IS NOT NULL AND pg_temp.as_uuid("sourceUserId") IS NULL
UNION ALL
SELECT 'text_id_not_uuid', id::text, 'ConsentRecord.targetId=' || "targetId"
FROM "ConsentRecord" WHERE "targetId" IS NOT NULL AND pg_temp.as_uuid("targetId") IS NULL;
-- A text id that becomes a uuid FK is not uuid-shaped (step 17).
-- UPDATE "<table>" SET "<column>" = NULL WHERE id IN (<ids>);  -- or the right id

-- ----------------------------------------------------------------------------
-- P26 declination_need_unresolved (step 17: Stage4NeedDeclination.needId found)
-- ----------------------------------------------------------------------------
SELECT 'declination_need_unresolved', d.id::text, d."needId"
FROM "Stage4NeedDeclination" d
WHERE pg_temp.as_uuid(d."needId") IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "IdentifiedNeed" n WHERE n.id = pg_temp.as_uuid(d."needId"));
-- A declination of a need that no longer exists.
-- DELETE FROM "Stage4NeedDeclination" WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P27 intensity_out_of_range (intensity domain 1..10)
-- ----------------------------------------------------------------------------
SELECT 'intensity_out_of_range', id::text, 'EmotionalReading.intensity=' || intensity
FROM "EmotionalReading" WHERE intensity NOT BETWEEN 1 AND 10
UNION ALL
SELECT 'intensity_out_of_range', id::text, format('EmotionalExerciseCompletion before=%s after=%s', "intensityBefore", "intensityAfter")
FROM "EmotionalExerciseCompletion"
WHERE "intensityBefore" NOT BETWEEN 1 AND 10 OR "intensityAfter" NOT BETWEEN 1 AND 10;
-- The intensity domain is 1..10.
-- UPDATE "EmotionalReading" SET intensity = least(greatest(intensity, 1), 10) WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P28a summary_not_json_object (conversationSummary text → jsonb, RAISE on invalid JSON)
-- ----------------------------------------------------------------------------
SELECT 'summary_not_json_object', 'UserVessel:' || id::text, left("conversationSummary", 60)
FROM "UserVessel"
WHERE "conversationSummary" IS NOT NULL
  AND (NOT pg_input_is_valid("conversationSummary", 'jsonb') OR jsonb_typeof("conversationSummary"::jsonb) <> 'object'
       OR NOT ("conversationSummary"::jsonb ?& ARRAY['text', 'messageCount', 'generatedAt']))
UNION ALL
SELECT 'summary_not_json_object', 'InnerWorkSession:' || id::text, left("conversationSummary", 60)
FROM "InnerWorkSession"
WHERE "conversationSummary" IS NOT NULL
  AND (NOT pg_input_is_valid("conversationSummary", 'jsonb') OR jsonb_typeof("conversationSummary"::jsonb) <> 'object');
-- conversationSummary is parsed into jsonb; an invalid one, or a vessel
-- summary without text/messageCount/generatedAt, cannot be. Regenerate or null.
-- UPDATE "UserVessel" SET "conversationSummary" = NULL WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P28b facts_shape (ai_memory *_FACTS doc requires a facts array)
-- ----------------------------------------------------------------------------
SELECT 'facts_shape', 'UserVessel:' || id::text, jsonb_typeof("notableFacts")
FROM "UserVessel"
WHERE pg_temp.jnull("notableFacts") IS NOT NULL
  AND jsonb_typeof("notableFacts") <> 'array'
  AND NOT (jsonb_typeof("notableFacts") = 'object' AND jsonb_typeof("notableFacts" -> 'facts') = 'array')
UNION ALL
SELECT 'facts_shape', 'User:' || id::text, jsonb_typeof("globalFacts")
FROM "User"
WHERE pg_temp.jnull("globalFacts") IS NOT NULL
  AND jsonb_typeof("globalFacts") <> 'array'
  AND NOT (jsonb_typeof("globalFacts") = 'object' AND jsonb_typeof("globalFacts" -> 'facts') = 'array');
-- *_FACTS documents hold a facts array.
-- UPDATE "UserVessel" SET "notableFacts" = NULL WHERE id IN (<ids>);

-- ----------------------------------------------------------------------------
-- P28c jsonb_not_container (CHECK jsonb_typeof on every jsonb column)
-- ----------------------------------------------------------------------------
SELECT 'jsonb_not_container', 'BrainActivity:' || id::text,
       format('input=%s output=%s metadata=%s structuredOutput=%s', jsonb_typeof(input), jsonb_typeof(output), jsonb_typeof(metadata), jsonb_typeof("structuredOutput"))
FROM "BrainActivity"
WHERE coalesce(jsonb_typeof(input), 'null') NOT IN ('object', 'array', 'null')
   OR coalesce(jsonb_typeof(output), 'null') NOT IN ('object', 'array', 'null')
   OR coalesce(jsonb_typeof(metadata), 'null') NOT IN ('object', 'array', 'null')
   OR coalesce(jsonb_typeof("structuredOutput"), 'null') NOT IN ('object', 'array', 'null')
UNION ALL
SELECT 'jsonb_not_container', 'User:' || id::text,
       format('memory=%s notifications=%s privacy=%s', jsonb_typeof("memoryPreferences"), jsonb_typeof("notificationPreferences"), jsonb_typeof("privacyPreferences"))
FROM "User"
WHERE coalesce(jsonb_typeof("memoryPreferences"), 'null') NOT IN ('object', 'null')
   OR coalesce(jsonb_typeof("notificationPreferences"), 'null') NOT IN ('object', 'null')
   OR coalesce(jsonb_typeof("privacyPreferences"), 'null') NOT IN ('object', 'null');
-- Every jsonb column holds an object (or array where allowed).
-- UPDATE "BrainActivity" SET input = jsonb_build_object('value', input) WHERE id IN (<ids>);

