-- P32 brain_cost_overflow (cost numeric(10,6))
-- ----------------------------------------------------------------------------
SELECT 'brain_cost_overflow', id::text, cost::text
FROM "BrainActivity"
WHERE abs(cost) >= 10000;
-- cost becomes numeric(10,6).
